-- PT107-S1-Q10. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT107-S1-Q10$batch03$ AND q.stimulus=$batch03$The symptoms of hepatitis A appear no earlier than 60 days after a person has been infected. In a test of a hepatitis A vaccine, 50 people received the vaccine and 50 people received a harmless placebo. Although some people from each group eventually exhibited symptoms of hepatitis A, the vaccine as used in the test is completely effective in preventing infection with the hepatitis A virus.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps resolve the apparent discrepancy in the information above?$batch03$ AND q.correct_choice=$batch03$D$batch03$) THEN RAISE EXCEPTION 'Question changed: PT107-S1-Q10'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT107-S1-Q10$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT107-S1-Q10'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT107-S1-Q10$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$The vaccine is completely effective at preventing hepatitis A infection.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Some vaccinated people in the test later showed symptoms of hepatitis A?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$The first sentence is a breadcrumb: symptoms appear at least 60 days *after* infection. So a person can show symptoms long after they were infected. If some vaccinated people were already infected before the shot, a perfect vaccine could not prevent an infection that had already happened.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Look for vaccinated people who were infected before vaccination.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT107-S1-Q10$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$This is about the placebo group. It does not explain why people in the *vaccine* group got symptoms.$batch03$), ($batch03$B$batch03$, $batch03$Who recognized their symptoms does not change who had them. Vaccinated people still showed symptoms.$batch03$), ($batch03$C$batch03$, $batch03$Overall fitness might affect how sick someone gets, but a completely effective vaccine should prevent infection regardless.$batch03$), ($batch03$D$batch03$, $batch03$The vaccine prevents infection; it cannot undo one that already happened. With a 60-day delay before symptoms, people infected before the shot would show symptoms afterward. The vaccine is still completely effective.$batch03$), ($batch03$E$batch03$, $batch03$Faster recovery says the vaccinated people were still infected. That is the puzzle, not the explanation.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT107-S1-Q10$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
